create table public.expense_categories (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,"categoryName" text not null,"categoryDescription" text,status boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,"categoryName"));
create table public.income_categories (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,"categoryName" text not null,"categoryDescription" text,status boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,"categoryName"));
create table public.expenses (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,amount numeric(14,2) not null check(amount>=0),expense_category_id bigint references public.expense_categories(id) on delete set null,expanse_for text,payment_type text not null default 'Cash',reference_no text,note text,expense_date timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.incomes (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,amount numeric(14,2) not null check(amount>=0),income_category_id bigint references public.income_categories(id) on delete set null,income_for text,payment_type text not null default 'Cash',reference_no text,note text,income_date timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ declare t text; begin for t in select unnest(array['expense_categories','income_categories','expenses','incomes']) loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on table public.%I from anon,authenticated',t); execute format('grant select,insert,update,delete on table public.%I to authenticated',t); execute format('create policy %I on public.%I for all to authenticated using (business_id=(select private.current_business_id())) with check (business_id=(select private.current_business_id()))',t||'_tenant_policy',t); end loop; end $$;
create index expenses_business_date_idx on public.expenses(business_id,expense_date);
create index incomes_business_date_idx on public.incomes(business_id,income_date);